const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');

const scrypt = promisify(crypto.scrypt);

const PROD = process.env.NODE_ENV === 'production';
const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET) {
  throw new Error('SESSION_SECRET must be set');
}

// --- Password hashing (scrypt, OWASP-recommended parameters) ---------------

const SCRYPT = { N: 2 ** 15, r: 8, p: 3, maxmem: 64 * 1024 * 1024 };
const KEY_LEN = 64;
const MAX_PASSWORD_LEN = 1024;

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password.normalize('NFKC'), salt, KEY_LEN, SCRYPT);
  // Parameters are stored with the hash so they can be raised later.
  return ['scrypt', SCRYPT.N, SCRYPT.r, SCRYPT.p, salt.toString('base64'), key.toString('base64')].join('$');
}

async function verifyPassword(password, stored) {
  const [scheme, N, r, p, salt, hash] = stored.split('$');
  if (scheme !== 'scrypt') return false;
  const expected = Buffer.from(hash, 'base64');
  const actual = await scrypt(password.normalize('NFKC'), Buffer.from(salt, 'base64'), expected.length, {
    N: Number(N),
    r: Number(r),
    p: Number(p),
    maxmem: SCRYPT.maxmem,
  });
  return crypto.timingSafeEqual(actual, expected);
}

// --- User store (in-memory stand-in for a database) ------------------------

const users = new Map(); // normalized username -> { id, username, passwordHash }

const normalizeUsername = (username) => username.trim().toLowerCase();

// Verified against when the username is unknown, so that response time does
// not reveal whether an account exists.
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// --- App -------------------------------------------------------------------

const app = express();

// Behind a reverse proxy, set TRUST_PROXY to the number of proxy hops so that
// req.ip (used for rate limiting) and secure cookies work correctly.
if (process.env.TRUST_PROXY) {
  app.set('trust proxy', Number(process.env.TRUST_PROXY));
}

app.disable('x-powered-by');
app.use(express.json({ limit: '10kb' }));

app.use(
  session({
    name: 'sid',
    secret: SESSION_SECRET,
    resave: false,
    saveUninitialized: false,
    // The default MemoryStore is for development only; use a persistent store
    // (e.g. connect-redis) in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: PROD,
      maxAge: 8 * 60 * 60 * 1000,
    },
  })
);

// --- Rate limiting of failed attempts --------------------------------------

const WINDOW_MS = 15 * 60 * 1000;
const tooManyAttempts = { error: 'Too many failed login attempts. Try again later.' };

// Only failed attempts (status >= 400) count against either limit.
const ipLimiter = rateLimit({
  windowMs: WINDOW_MS,
  limit: 20,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: tooManyAttempts,
});

// Keyed on the targeted account, so guesses spread across many IPs are still
// throttled.
const accountLimiter = rateLimit({
  windowMs: WINDOW_MS,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: false,
  legacyHeaders: false,
  keyGenerator: (req) => {
    const username = req.body?.username;
    return typeof username === 'string' ? normalizeUsername(username).slice(0, 64) : '';
  },
  message: tooManyAttempts,
});

// --- Routes ----------------------------------------------------------------

function parseCredentials(body) {
  const { username, password } = body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  if (!username.trim() || username.length > 64) return null;
  if (!password || password.length > MAX_PASSWORD_LEN) return null;
  return { username: normalizeUsername(username), password };
}

function requireAuth(req, res, next) {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  next();
}

app.post('/register', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds || creds.password.length < 8) {
    return res.status(400).json({ error: 'Username and a password of at least 8 characters are required' });
  }
  if (users.has(creds.username)) {
    return res.status(409).json({ error: 'Username is taken' });
  }
  const user = {
    id: crypto.randomUUID(),
    username: creds.username,
    passwordHash: await hashPassword(creds.password),
  };
  users.set(user.username, user);
  res.status(201).json({ id: user.id, username: user.username });
});

app.post('/login', ipLimiter, accountLimiter, async (req, res, next) => {
  const creds = parseCredentials(req.body);
  if (!creds) {
    return res.status(400).json({ error: 'Username and password are required' });
  }

  const user = users.get(creds.username);
  const valid = await verifyPassword(creds.password, user ? user.passwordHash : await dummyHash);
  if (!user || !valid) {
    // Same response for unknown user and wrong password.
    return res.status(401).json({ error: 'Invalid username or password' });
  }

  // New session ID on privilege change, to prevent session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    req.session.username = user.username;
    req.session.save((err) => {
      if (err) return next(err);
      res.json({ id: user.id, username: user.username });
    });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

if (require.main === module) {
  const port = Number(process.env.PORT) || 3000;
  app.listen(port, () => console.log(`Listening on http://localhost:${port}`));
}

module.exports = app;

